def run_vector_db_test(client, collection_name, embedded_query):
    # Only Qdrant uses this helper (the lab-engine client tests were removed from CI).
    # Qdrant indexes synchronously and returns a QueryResponse with .points.
    try:
        client.create_collection(collection_name)
        client.push_documents(
            collection_name=collection_name,
            ids=[POINT_ID],
            queries=["test query"],
            embedded_queries=[embedded_query],
        )
        response = client.retrieve_query(
            collection_name=collection_name,
            embedded_query=embedded_query,
        )
        assert len(response.points) > 0
    finally:
        client.delete_collection(collection_name)